local _, WFI = ...
WFI.Data.add("quest", {
  [1042] = { "La famiglia Carevin", "Parla con Jonathan Carevin, a Darkshire.", "No, non ho notizie di una certa Velinde Starsong che abbia alloggiato a Darkshire... anche se, se mi permetti, non riesco proprio a immaginare una sacerdotessa elfa della notte che prenda una stanza alla locanda, se capisci cosa intendo.\n\nQuesti uomini-lupo di cui parli, invece, sono una cosa di cui ho sentito parlare. Proprio l'altro giorno Calor è arrivato in paese con una fila delle loro teste. Lavora con la famiglia Carevin: cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è il capofamiglia.", nil, "Tempi bui sono questi. Notizie funeste sussurrano da ogni ramo che ondeggia, e il male si trova sotto ogni pietra.\n\nE in tempi simili, uno sconosciuto entra in casa mia e chiede dei worgen... Non chiederò perdono per i miei sospetti, solo risposte.\n\nE risposte avrò.", 0x5b4165bb, 0x260919bb, 0x60b610fd, nil, 0xa9084ff2, "...m." },
  [1043] = { "La Scythe of Elune", "Cerca tracce della Scythe of Elune, poi torna da Jonathan Carevin a Darkshire.", "La tua storia suona vera... Non capisco del tutto le tue ragioni, ma se i tuoi affari qui a Duskwood riguardano lo sterminio dei worgen nella foresta, in qualunque numero, allora posso rinunciare a capire in cambio dei risultati.\n\nC'è una miniera a sud che è stata invasa dai worgen... Sono comparsi dal nulla, ma da quanto sappiamo è lì che sono stati trovati per la prima volta.\n\nFai pure i tuoi affari, ma ti chiederei, se trovi qualcosa di importante, di condividerlo con me. Accettiamo qualunque aiuto nella nostra guerra contro il male.", "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e il cervello ancora di più, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.", "Racconti una storia interessante, {name}. Anche se l'influenza della famiglia Carevin non basta per trovare la radice di questi problemi e risolverli una volta per tutte, faremo il possibile per contenere il numero dei worgen a Duskwood.\n\nHo già detto a Calor di farne la sua priorità.", 0x0767908c, 0x803b9a4e, 0x6cd0e968, 0x9f8262d0, 0x837fbc53, "....." },
  [1044] = { "Domande con risposta", "Torna da Thyn'tel Bladeweaver, a Darnassus.", "Terremo a freno il problema dei worgen, non temere. Il male che la tua amica ha portato nei nostri boschi sarà contenuto, e non le serbo rancore per ciò che ha fatto. In questi tempi accadono cose strane, {name}, e l'oscurità non conosce tregua.\n\nNon ti trattengo oltre. Immagino che ci siano altri che dovrebbero sapere cosa hai trovato nelle miniere di Duskwood.", nil, "Dunque è questa la sorte di Velinde? L'alta sacerdotessa sarà delusa di saperlo: prima della sua scomparsa erano buone amiche. Eppure la Scythe of Elune le era stata di certo concessa come dono dalla nostra dea, e mi turba che sia sfuggita dalle mani delle sue serve.\n\nMa questa è un'altra faccenda, per un'altra volta. Ti devo un grande ringraziamento per ciò che hai fatto.", 0x44407ecd, 0xb8c245b0, 0x8d9eb68f, nil, 0x9bb2d02d, "...m." },
  [1097] = { "Il compito di Elmore", "Parla con Grimand Elmore.", "C'è un fabbro d'armi nanico a Stormwind, Grimand Elmore, che ha fatto sapere che gli serve aiuto per una consegna. Credo voglia spedire un pacco nella sua patria, al nord.\n\nHai un bel paio di gambe robuste! Quindi, se ti va di camminare un po', parla con Grimand. Qui ci servi, ma dobbiamo anche mantenere saldi i legami con i nani.\n\nTrovi Grimand Elmore nella bottega d'armi del Dwarven District di Stormwind, nella parte nord-est della città.", nil, "Sei qui per aiutarmi con la consegna? Molto bene!", 0x30749260, 0x6ac05387, 0xf12b5a6f, nil, 0x7d006a0a, "...m." },
  [1132] = { nil, "Parla con Fiora Longears, a Theramore.", "Oh, essere di nuovo in mare! Sentire il bacio del vento, e farmi cullare dalle onde come dalla mia benedetta madre, tanto tempo fa!\n\nOh, vorrei avere la tua fortuna, buon {class}, perché vedo il mare nel tuo futuro!\n\nIl mio lavoro è parlare alle anime desiderose della terra di Kalimdor, la terra delle opportunità! Se vuoi tentare la fortuna oltre il mare, prendi una nave da qui per il bel porto di Theramore. Lì parla con la mia socia, l'elfa Fiora Longears.\n\nTi farà cominciare la tua avventura a Kalimdor!", nil, "Buongiorno a te! Ti manda Mr. Flint di Menethil Harbor? Be', Mr. Flint sa giudicare le persone. Se ti ha mandato lui, non c'è dubbio che il tuo posto sia qui a Kalimdor!", nil, 0x79d16431, 0x1e6af9aa, nil, 0xf87f590d, "m..m." },
  [1241] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1242] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1243] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1244] = { "Il diplomatico scomparso", "Trova il Defias Docket e riportalo a Watcher Backus, a Duskwood.", "Attività dei Defias? Be', c'è sempre qualche attività: anche se se ne stanno per conto loro, li consideriamo una minaccia.\n\nMa ora che ci penso, c'è stato un avvistamento recente che mi è sembrato strano. Dev'essere stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno all'Addle's Stead. Dal rapporto, avrei detto che stava succedendo qualcosa di grosso.\n\nPerché non vai a controllare lì e mi riporti quello che trovi?\n\nLa fattoria è a sud della strada che viene da Westfall, appena entri a Duskwood.", "Stai <attento/attenta> là fuori, {name}. So che ti ha mandato qui Trias, ma questo non vuol dire che nei boschi non ci sia in agguato qualcosa che possa darti dei guai... soprattutto ora che indaghi sui Defias.", "Sei <tornato/tornata> <sano/sana> e <salvo/salva>. Non si potrebbe chiedere di meglio, no?\n\nOra vediamo cos'abbiamo qui. Sembra piuttosto ufficiale, rispetto ai documenti dei Defias che ho visto. Ma potrebbe essere un trucco solo per sviarti da qualunque cosa tu stia cercando.", 0xbe525a75, 0x48feff50, 0xea67aecc, 0xcea0ed63, 0x67804e8a, "....." },
  [1245] = { "Il diplomatico scomparso", "Porta il Defias Docket a Elling Trias, a Stormwind.", "Accidenti, questo è troppo complicato per essere solo un modo per sviarti. Non dovrei nemmeno guardare questa roba. Portala a Trias: lui saprà capirci qualcosa. E non lasciare per nessun motivo che qualcuno ti ostacoli. È più grande di me. Forse è più grande persino di lui, ma vedremo.\n\nE fammi un favore, {name}: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo qualcosa di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.", "Vedo che sei <tornato/tornata>, e tutto d'un pezzo. Sappiamo entrambi che non sei qui per il formaggio, quindi lasciamo perdere i convenevoli. Backus ti è stato d'aiuto, o non sei nemmeno <partito/partita> per Duskwood?", "Sì... questa è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.\n\nSembra che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Mmm... cos'è questo? \"Fist\"? È un nome che mi suona familiare.", 0xbe525a75, 0xa98e158b, 0xfafe092f, 0x24e86e52, 0x8bf38d0b, "....." },
  [1246] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1247] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
