  [1301] = { nil, "Parla con Vincent Hyal, a Menethil Harbor.", "Prima di lavorare qui al Blue Recluse, sono stato istruito da uno dei migliori cuochi e locandieri che abbia mai conosciuto. Si chiamava James Hyal. Tutto quello che ho e tutto quello che ho ottenuto nella vita lo devo a lui.\n\nChissà come sta. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma ultimamente non ho sue notizie.\n\nSe mai ti capitasse di andare da quelle parti, potresti salutarlo da parte mia?", nil, "James? Oh, se n'è andato da un pezzo.\n\nGli è tornato il patriottismo, immagino. Non è difficile capire perché. Con tutta la follia a Lordaeron, molti si sono uniti a Jaina Proudmoore quando è partita oltre il mare.", nil, 0xc1cf5639, 0x894d2527, nil, 0xb47d985d, "m..m." },
  [1302] = { nil, "Parla con Clerk Lendry, a Theramore.", "Mio fratello James è partito oltre il mare con Lady Proudmoore. L'ultima volta che ho saputo qualcosa, laggiù i combattimenti si erano calmati e James stava aprendo una locanda da qualche parte nel continente. Ovunque sia, di sicuro fa buoni affari. Era un cuoco dannatamente bravo.\n\nÈ da un po' che non ho sue notizie, troppo preso dalla locanda, scommetto, ma l'impiegato di Theramore potrebbe probabilmente indicarti dove trovarlo.", nil, "James Hyal, James Hyal... Perché questo nome mi suona così familiare?\n\nMa certo! L'incidente dello Shady Rest Inn. Se hai informazioni su quello che è successo lì, ti consiglio vivamente di parlarne con Captain Vimes. È lui che si occupa dell'indagine.", nil, 0x1cc2fc0c, 0x228dd9c4, nil, 0x331f172f, "m..m." },
  [1324] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1338] = { "L'ordine di Stormpike", "Porta la Stormpike's Request a Furen Longbeard, a Stormwind.", "C'è un armaiolo nanico di cui ammiro molto il lavoro. Si chiama Furen Longbeard, e la sua abilità non ha pari. Mi serve un nuovo scudo, e devo averne uno dei suoi!\n\nIl problema è che... Furen è molto a sud, nel quartiere nanico di Stormwind. In terra umana! Non riesco a immaginare perché viva là, così lontano da Ironforge. Gli umani devono pagarlo come un re per tenerlo lì!\n\nAllora, se ti va di viaggiare e non ti dispiace guadagnare qualcosa, porteresti a Furen la mia richiesta per uno scudo?", "Una lettera dalle terre naniche? Chissà chi mi scrive da così lontano a nord...\n\nTi prego, fammi vedere l'ordine.", "Ah, una richiesta da uno degli Stormpike. È un clan fiero, pieno di nani di qualità. E ricchi, anche.\n\nGrazie, {name}. Mi metterò al lavoro sullo scudo di Mountaineer Stormpike entro la fine della giornata.", 0xecf988f4, 0x130880f5, 0x24e88b1f, 0xd07031a3, 0xae03cdbb, "....." },
  [1395] = { "Rifornimenti per Nethergarde", "Porta la Crate of Powerstones a Quartermaster Lungertz prima che le powerstone si esauriscano.", "Questa cassa di powerstone deve arrivare alla Nethergarde Keep, nelle Blasted Lands. Non manterranno a lungo il loro potere, quindi non possiamo spedirle con la prossima carovana.\n\nDevi portarle tu, e devi portarle in fretta.\n\nPortale a Quartermaster Lungertz, alla Nethergarde Keep. Per raggiungere la fortezza devi viaggiare verso est attraverso il Deadwind Pass, poi verso est attraverso la Swamp of Sorrows, poi verso sud attraverso le Blasted Lands.\n\nFai attenzione, {name}. Attraverserai terre pericolose, eppure non devi fallire.", "Salve! Non badare a tutto questo trambusto, è la solita routine alla Nethergarde Keep.\n\nHai qualcosa per me?", "Ah, le powerstone! I maghi saranno felici di vederle!\n\nMille grazie, {name}. So che il viaggio da Darkshire non è stato facile.", 0xa26e9783, 0x6e0883b5, 0x5e29a42b, 0x59251ed0, 0x8d183396, "....." },
  [1447] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1598] = { "Il tomo rubato", "Recupera i Powers of the Void per Drusilla La Salle.", "Ehi, tu! {name}, giusto?\n\nSpero che tu sia <convinto/convinta> di voler diventare <uno/una> <stregone/strega>, perché se non sai cavartela da <solo/sola>, finirai per farti trascinare a fondo.\n\nDevo istruirti, ma prima devo assicurarmi che tu sia abbastanza forte.\n\nC'era un novizio che studiava all'abbazia ed è scappato per unirsi alla Defias Brotherhood. Perché mi interessa? Be', ha rubato alcuni libri importanti.\n\nUno di questi è proprio un libro che volevo per me, i Powers of the Void. Rubalo per me: lo tengono nascosto nella loro tenda nei vigneti.", "Rubare il libro di persona avrebbe dato troppo nell'occhio. Che fortuna che uno dei loro tirapiedi abbia fatto il lavoro sporco per me.", "Eccellente... Non sono mai riuscita a mettere le mani su questo testo: era custodito in un'ala protetta della biblioteca, e aggirarmi da quelle parti sarebbe sembrato sospetto.\n\nBe', hai fatto un buon lavoro a procurartelo, e sono convinta che tu sia in grado di gestire un imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.", 0x88b1dee6, 0x8e23bc14, 0x4748064a, 0xdb594d3a, 0x048d8e41, "....." },
  [1638] = { "L'addestramento di un guerriero", "Parla con Harry Burlguard.", "Hai dimostrato di essere <un/una> <guerriero/guerriera> capace, {name}. Ma sei ancora giovane e hai molto da imparare.\n\nParla con Harry Burlguard: di solito è alla taverna Pig and Whistle, nella Old Town di Stormwind. Harry è un vecchio veterano e un buon maestro. Può insegnarti qualche mossa che ti terrà in vita più a lungo.", nil, "Oh oh! Bevi qualcosa con me, {name}. Fuori sembri una persona tosta, ma vediamo se il tuo stomaco regge qualche boccale del più forte del Pig and Whistle!!\n\nOppure... eri qui per una lezione?", 0x93c881d5, 0x0aef52fa, 0x0ff82d16, nil, 0x11af52b0, "...m." },
  [1641] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1642] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, 0xe91f21c0, 0x0f3ca705, nil, nil, nil, "..mmm" },
  [1643] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1644] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
